#!/bin/bash
# lfs.sh (Vetro su Arch): generato da arch/costruisci.sh (i sorgenti sono in arch/src e arch/file)
set -Eeuo pipefail
# ===== 00-testa.sh
# =============================================================================
#  lfs.sh — Vetro su Arch Linux: il desktop "Vetro" (leggero, sicurezza:
#  modalita' fantasma, firewall, Guardiano della rete, VPN...). Un solo file.
#
#  Sul tuo PC, con una macchina virtuale:
#    sudo bash lfs.sh fase10      crea la macchina con Arch e Vetro, o aggiorna Vetro
#    sudo bash lfs.sh avvia       la accende con lo schermo
#    sudo bash lfs.sh registri    raccoglie i registri della macchina
#    sudo bash lfs.sh controlla   dice come sta la macchina
#  Dentro un Arch gia' installato (anche un PC vero):
#    sudo bash lfs.sh installa    installa o aggiorna Vetro (riprende da dove era)
#    sudo bash lfs.sh controlla | registri | rifai PASSO
#
#  Ogni passo, se si ferma, si riprende rilanciando lo script; se lo script
#  cambia un passo, quel passo si rifa' da solo.
# =============================================================================

# tutto quello che lo script scrive passa da qui (vuota = il disco vero; le prove
# usano una cartella finta)
VETRO_RADICE=${VETRO_RADICE:-}
VETRO_FILE=${VETRO_FILE:-}
FASE1=() FASE2=() FASE3=() FASE4=()

percorso() { printf '%s%s\n' "$VETRO_RADICE" "$1"; }
VETRO_STATO=$(percorso /var/lib/vetro-arch)

titolo() { printf '\n==> %s\n' "$*"; }
info()   { printf '  %s\n' "$*"; }
ok()     { printf '  [OK] %s\n' "$*"; }
avviso() { printf '  [!!] %s\n' "$*" >&2; }
muori()  { printf '\n  [ERRORE] %s\n\n' "$*" >&2; exit 1; }

serve_root() {
    [ "${VETRO_EUID:-$EUID}" -eq 0 ] || muori "Lancialo come root:  sudo bash lfs.sh ${1:-}"
}

controlla_arch() {
    [ -f "$(percorso /etc/arch-release)" ] \
        || muori "Questo script e' fatto per Arch Linux (non trovo /etc/arch-release)"
}

# i comandi che cambiano il sistema (pacman, systemctl, useradd...) passano da qui:
# nelle prove si usano quelli finti, e un comando senza finto non parte mai
esegui() {
    if [ -n "$VETRO_RADICE" ]; then
        if [ -x "$VETRO_RADICE/.finti/${1##*/}" ]; then
            "$VETRO_RADICE/.finti/${1##*/}" "${@:2}"
            return
        fi
        echo "prova: manca il comando finto per '$1'" >&2
        return 127
    fi
    "$@"
}

# installa_file REL...: copia i file dello script (cartella file/) sul disco, con
# gli stessi permessi
installa_file() {
    local rel src dst
    for rel in "$@"; do
        src="$VETRO_FILE/$rel"
        dst=$(percorso "/$rel")
        [ -f "$src" ] || muori "Nello script manca il file $rel"
        install -D -m "$(stat -c %a "$src")" "$src" "$dst"
    done
}

# installa_cartella REL...: come installa_file, per tutti i file di una cartella
installa_cartella() {
    local rel f
    for rel in "$@"; do
        [ -d "$VETRO_FILE/$rel" ] || muori "Nello script manca la cartella $rel"
        while IFS= read -r f; do
            installa_file "$f"
        done < <(cd "$VETRO_FILE" && find "$rel" -type f | LC_ALL=C sort)
    done
}
# ===== 10-passi.sh
# --- il motore dei passi ----------------------------------------------------------
# Ogni passo ha un segno in $VETRO_STATO/fatto/NOME con l'impronta del suo testo e
# dei suoi file: se e' uguale il passo e' gia' fatto, se cambia si rifa'.

# impronta FUNZIONE [REL...]: sha256 del testo della funzione e dei file elencati
impronta() {
    local fn=$1 rel
    shift
    {
        declare -f "$fn"
        for rel in "$@"; do
            if [ -d "$VETRO_FILE/$rel" ]; then
                # una cartella: tutti i file dentro, in ordine, con il loro nome
                (cd "$VETRO_FILE" && find "$rel" -type f | LC_ALL=C sort | while IFS= read -r f; do
                    printf '== %s\n' "$f"; cat "$f"; done)
            else
                printf '== %s\n' "$rel"
                cat "$VETRO_FILE/$rel" 2>/dev/null || true
            fi
        done
    } | sha256sum | cut -d' ' -f1
}

# passo NOME FUNZIONE [REL...]: esegue la funzione (se non gia' fatta) con il suo
# registro; se si ferma mostra le ultime righe e lo script esce
passo() {
    local nome=$1 fn=$2
    shift 2
    local segno="$VETRO_STATO/fatto/$nome" registro="$VETRO_STATO/registri/$nome.log" imp esito=0
    imp=$(impronta "$fn" "$@")
    if [ -f "$segno" ] && [ "$(cat "$segno")" = "$imp" ]; then
        info "$nome (gia' fatto)"
        return 0
    fi
    mkdir -p "$VETRO_STATO/fatto" "$VETRO_STATO/registri"
    info "$nome..."
    # in sottofondo e non dentro un "if": cosi' "fermati al primo errore" vale davvero
    ( set -Eeuo pipefail; "$fn" ) > "$registro" 2>&1 < /dev/null &
    wait "$!" || esito=$?
    if [ "$esito" -ne 0 ]; then
        tail -n 15 "$registro" | sed 's/^/      | /' >&2
        muori "Il passo \"$nome\" non e' riuscito (registro: $registro). Rilancia lo script: riparte da qui."
    fi
    printf '%s\n' "$imp" > "$segno"
    grep -F '[OK]' "$registro" | sed 's/^ */    /' || true
    ok "$nome"
}

rifai_passo() { rm -f "$VETRO_STATO/fatto/$1"; }

# esegui_fase RIGA...: ogni riga e' "nome|funzione|file1 file2"
esegui_fase() {
    local riga nome fn file
    for riga in "$@"; do
        IFS='|' read -r nome fn file <<<"$riga"
        # shellcheck disable=SC2086
        passo "$nome" "$fn" $file
    done
}
# ===== 20-pacchetti.sh
# --- pacchetti: solo i repository ufficiali di Arch (core, extra, multilib) --------
# Le liste le riempiono le fasi (PKG_FASE1..PKG_FASE4). Quickshell si compila sempre dai
# sorgenti, alla versione che vuole Caelestia (vedi 45-caelestia.sh).
PKG_FASE1=() PKG_FASE2=() PKG_FASE3=() PKG_FASE4=()

QUICKSHELL_DIPENDENZE=(cmake ninja pkgconf qt6-base qt6-declarative qt6-wayland qt6-svg
                       qt6-shadertools spirv-tools wayland wayland-protocols cli11 libdrm
                       mesa vulkan-headers libxcb pipewire jemalloc pam polkit glib2 git)

# multilib serve per Wine (i programmi Windows a 32 bit)
abilita_multilib() {
    local conf; conf=$(percorso /etc/pacman.conf)
    [ -f "$conf" ] || muori "Non trovo $conf"
    sed -i '/^#\[multilib\]$/{s/^#//;n;s/^#Include/Include/}' "$conf"
    esegui pacman -Sy --noconfirm >/dev/null
    ok "Repository multilib acceso"
}

# controlla_pacchetti PKG...: esce con 1 (e dice quali) se qualcuno non c'e'
controlla_pacchetti() {
    local p mancanti=()
    for p in "$@"; do
        esegui pacman -Si "$p" >/dev/null 2>&1 || mancanti+=("$p")
    done
    if [ "${#mancanti[@]}" -gt 0 ]; then
        avviso "Nei repository di Arch non trovo: ${mancanti[*]}"
        return 1
    fi
}

controlla_tutti_i_pacchetti() {
    local tutti=() p
    for p in "${PKG_FASE1[@]}" "${PKG_FASE2[@]}" "${PKG_FASE3[@]}" "${PKG_FASE4[@]}"; do
        [ "$p" = quickshell ] || tutti+=("$p")     # Quickshell: vedi installa_quickshell
    done
    [ "${#tutti[@]}" -gt 0 ] || return 0
    info "Controllo che i ${#tutti[@]} pacchetti ci siano tutti..."
    controlla_pacchetti "${tutti[@]}" \
        || muori "Mancano dei pacchetti: lo script va aggiornato (mandami questo messaggio)"
    ok "Ci sono tutti i pacchetti"
}

# installa_pacchetti PKG...: fino a 3 tentativi (la rete a volte si interrompe)
installa_pacchetti() {
    local volta
    for volta in 1 2 3; do
        if esegui pacman -S --needed --noconfirm "$@"; then return 0; fi
        avviso "pacman non e' riuscito (tentativo $volta di 3)"
        [ -n "$VETRO_RADICE" ] || sleep $((volta * 5))
    done
    muori "Non riesco a installare: $*"
}

# Caelestia vuole Quickshell alla sua versione git (non quella dei repository)
installa_quickshell() {
    compila_quickshell
}

compila_quickshell() {
    info "Compilo Quickshell alla versione che usa Caelestia (qualche minuto)"
    installa_pacchetti "${QUICKSHELL_DIPENDENZE[@]}"
    local t; t=$(mktemp -d)
    scarica_git "$QUICKSHELL_GIT_URL" "$QUICKSHELL_COMMIT" "$t/quickshell"
    esegui cmake -S "$t/quickshell" -B "$t/build" -G Ninja -DCMAKE_BUILD_TYPE=RelWithDebInfo \
        -DCMAKE_INSTALL_PREFIX=/usr -DDISTRIBUTOR="oversicaOS" -DCRASH_HANDLER=OFF \
        -DGIT_REVISION="$QUICKSHELL_COMMIT"
    esegui ninja -C "$t/build"
    esegui ninja -C "$t/build" install
    rm -rf "$t"
    ok "Quickshell compilato e installato"
}
# ===== 30-fase1-sistema.sh
# --- Fase 1: sistema leggero ---------------------------------------------------------
PKG_FASE1=(zram-generator python sudo)
# il logo di oversicaOS, "Orbita" (disegnato da strumenti/disegna-logo.py)
FILE_LOGO="usr/share/icons/hicolor/scalable/apps/oversicaos.svg usr/share/icons/hicolor/scalable/apps/oversicaos-segno.svg usr/share/icons/hicolor/16x16/apps/oversicaos.png usr/share/icons/hicolor/24x24/apps/oversicaos.png usr/share/icons/hicolor/32x32/apps/oversicaos.png usr/share/icons/hicolor/48x48/apps/oversicaos.png usr/share/icons/hicolor/64x64/apps/oversicaos.png usr/share/icons/hicolor/128x128/apps/oversicaos.png usr/share/icons/hicolor/256x256/apps/oversicaos.png usr/share/icons/hicolor/512x512/apps/oversicaos.png"
FASE1=(
    "leggero|f1_leggero|etc/systemd/zram-generator.conf etc/systemd/oomd.conf.d/vetro.conf etc/systemd/journald.conf.d/vetro.conf"
    "utente|f1_utente|"
    "nome|f1_nome|etc/os-release $FILE_LOGO"
)

# il tuo utente: quello scritto in /etc/vetro/utente, altrimenti quello con UID 1000
# (lo crea archinstall), che poi si scrive li'
utente_vetro() {
    local f u; f=$(percorso /etc/vetro/utente)
    if [ -s "$f" ]; then cat "$f"; return 0; fi
    u=$(esegui getent passwd 1000 | cut -d: -f1)
    [ -n "$u" ] || muori "Non trovo il tuo utente (UID 1000): crealo con archinstall, poi rilancia"
    mkdir -p "$(dirname "$f")"
    printf '%s\n' "$u" > "$f"
    printf '%s\n' "$u"
}

f1_leggero() {
    installa_pacchetti "${PKG_FASE1[@]}"
    installa_file etc/systemd/zram-generator.conf etc/systemd/oomd.conf.d/vetro.conf \
                  etc/systemd/journald.conf.d/vetro.conf
    esegui systemctl enable systemd-oomd.service
    # servizi che qui non servono (la rete: NetworkManager, vedi l'ultimo passo)
    local s
    for s in cups.service; do
        if [ -e "$(percorso "/usr/lib/systemd/system/$s")" ]; then esegui systemctl disable --now "$s"; fi
    done
    if [ -e "$(percorso /usr/lib/systemd/system/bluetooth.service)" ] \
       && [ -z "$(ls -A "$(percorso /sys/class/bluetooth)" 2>/dev/null)" ]; then
        esegui systemctl disable --now bluetooth.service
    fi
    ok "Memoria compressa (zram), guardiano della memoria e registro leggero"
}

f1_utente() {
    local u; u=$(utente_vetro) || exit 1
    esegui usermod -aG wheel,video,input,audio "$u"
    local f; f=$(percorso /etc/sudoers.d/00-vetro)
    mkdir -p "$(dirname "$f")"
    printf '# vetro-arch.sh: chi e'"'"' nel gruppo wheel puo'"'"' usare sudo (con la password)\n%%wheel ALL=(ALL) ALL\n' > "$f"
    chmod 440 "$f"
    esegui visudo -cf "$f" >/dev/null
    ok "Utente $u: gruppi e sudo"
}

# il nome oversicaOS: /etc/os-release (prima era un collegamento al file di Arch: lo si
# sostituisce, quello di Arch resta com'e'), logo, nome del computer, voce di GRUB
f1_nome() {
    rm -f "$(percorso /etc/os-release)"
    # shellcheck disable=SC2086
    installa_file etc/os-release $FILE_LOGO
    esegui gtk-update-icon-cache -qtf "$(percorso /usr/share/icons/hicolor)" || true
    esegui hostnamectl set-hostname oversica || avviso "Non riesco a cambiare il nome del computer"
    local g; g=$(percorso /etc/default/grub)
    if [ -f "$g" ]; then
        if grep -q '^GRUB_DISTRIBUTOR=' "$g"; then
            sed -i 's|^GRUB_DISTRIBUTOR=.*|GRUB_DISTRIBUTOR="oversicaOS"|' "$g"
        else
            echo 'GRUB_DISTRIBUTOR="oversicaOS"' >> "$g"
        fi
        esegui grub-mkconfig -o /boot/grub/grub.cfg >/dev/null 2>&1 || avviso "Non riesco a rifare il menu di avvio"
    fi
    ok "Nome oversicaOS e logo"
}
# ===== 40-fase2-desktop.sh
# --- Fase 2: desktop Vetro con l'aspetto di GNOME ---------------------------------------
PKG_FASE2=(hyprland quickshell greetd xdg-desktop-portal-hyprland pipewire wireplumber
           pipewire-pulse adwaita-fonts adwaita-icon-theme gnome-themes-extra grim slurp
           swayidle swaylock libnotify jq git cmake ninja meson cpio base-devel)
FILE_DESKTOP="etc/xdg/quickshell/vetro etc/xdg/hypr usr/local/lib/vetro etc/gtk-3.0 etc/gtk-4.0
              usr/local/bin/avvia-desktop usr/local/bin/avvio-vetro usr/local/bin/avvia-pannelli
              usr/local/bin/blocca-schermo usr/local/bin/sfondo-desktop usr/local/bin/schermata
              usr/local/bin/oversica-config
              usr/local/bin/vetro-barre-aggiorna etc/pam.d/vetro-blocco
              etc/pacman.d/hooks/vetro-barre.hook usr/share/icons/default/index.theme
              usr/share/fonts/dm-sans usr/share/icons/hicolor/scalable/apps/vetro.svg etc/xdg/vetro
              usr/share/backgrounds"
FASE2=("desktop|f2_desktop|$(echo $FILE_DESKTOP)")

# il carattere delle icone dei pannelli (Material Symbols): non c'e' nei pacchetti
# ufficiali di Arch, si scarica da Google a una versione fissa e si controlla
FONT_ICONE_URL="https://github.com/google/material-design-icons/raw/10ecc14790612ca8fd164e3f4ffe9c16fc50d5b7/variablefont/MaterialSymbolsRounded%5BFILL,GRAD,opsz,wght%5D.ttf"
FONT_ICONE_SHA256=7e74e36533ccee12c2b81e75bfcf3ccf123d3bb7e7e46d65d94445f23db0c97c

installa_font_icone() {
    local dst tmp
    dst=$(percorso /usr/share/fonts/material-symbols/MaterialSymbolsRounded.ttf)
    if [ -f "$dst" ] && echo "$FONT_ICONE_SHA256  $dst" | sha256sum -c --status; then
        return 0
    fi
    tmp=$(mktemp)
    if ! esegui curl -fsSL --retry 3 -o "$tmp" "$FONT_ICONE_URL"; then
        rm -f "$tmp"
        muori "Non riesco a scaricare il carattere delle icone: controlla la rete e rilancia"
    fi
    if ! echo "$FONT_ICONE_SHA256  $tmp" | sha256sum -c --status; then
        rm -f "$tmp"
        muori "Il carattere delle icone scaricato non passa il controllo (sha256): rilancia piu' tardi"
    fi
    install -D -m 644 "$tmp" "$dst"
    rm -f "$tmp"
    esegui fc-cache -f
}

f2_desktop() {
    local senza=() p s
    for p in "${PKG_FASE2[@]}"; do [ "$p" = quickshell ] || senza+=("$p"); done
    installa_pacchetti "${senza[@]}"
    installa_quickshell
    # l'interfaccia di oversicaOS: Caelestia con i ritocchi (45-caelestia.sh)
    compila_caelestia
    installa_font_icone
    # i pannelli di Vetro di prima: li sostituisce Caelestia (resta la schermata di accesso)
    local vecchio
    for vecchio in "$(percorso /etc/xdg/quickshell/vetro)"/*; do
        [ -e "$vecchio" ] || continue
        case "${vecchio##*/}" in accesso.qml|AccessoVista.qml|PasswordPillola.qml) ;; *) rm -rf "$vecchio" ;; esac
    done
    for p in $FILE_DESKTOP; do
        if [ -d "$VETRO_FILE/$p" ]; then installa_cartella "$p"; else installa_file "$p"; fi
    done
    # i caratteri nuovi (DM Sans) si vedono subito
    esegui fc-cache -f
    # puntatori (freccia bianca col bordo nero spesso), disegnati con Python; gli sfondi
    # sono gia' pronti in usr/share/backgrounds
    esegui python3 -I "$(percorso /usr/local/lib/vetro/disegna-cursori)" "$(percorso /usr/share/icons/Vetro)"
    # barre del titolo: file vuoto finche' il plugin non c'e', poi il plugin. I vecchi
    # file .conf (Hyprland fino a 0.56) non servono piu'
    rm -f "$(percorso /etc/xdg/hypr/vetro.conf)" "$(percorso /etc/xdg/hypr/vetro-impostazioni.conf)" \
          "$(percorso /etc/xdg/hypr/vetro-barre.conf)"
    p=$(percorso /etc/xdg/hypr/vetro-barre.lua)
    [ -f "$p" ] || echo "-- Barre del titolo: vuoto finche' il plugin hyprbars non c'e'" > "$p"
    esegui "$(percorso /usr/local/bin/vetro-barre-aggiorna)"
    esegui systemctl --global enable pipewire.socket wireplumber.service pipewire-pulse.socket
    ok "Desktop di oversicaOS (Caelestia)"
}

# --- la schermata di accesso: greetd apre accesso.qml in un Hyprland tutto suo ----------
FASE2+=("accesso|f2_accesso|etc/greetd/config.toml etc/vetro/accesso-hyprland.lua")

f2_accesso() {
    installa_pacchetti greetd
    installa_file etc/greetd/config.toml etc/vetro/accesso-hyprland.lua
    rm -f "$(percorso /etc/vetro/accesso-hyprland.conf)"
    # l'utente "greeter" (lo crea il pacchetto greetd) deve poter usare la scheda video
    esegui usermod -aG video greeter
    esegui systemctl enable greetd.service
    # greetd usa la prima console: il login di testo li' non serve piu'
    esegui systemctl disable getty@tty1.service
    ok "Schermata di accesso (greetd)"
}


# --- i nomi dei siti (DNS): li chiede systemd-resolved (Quad9 cifrato, o Tor in modalita'
# fantasma). La rete vera e propria (NetworkManager) arriva all'ultimo passo.
FASE2+=("nomi|f2_nomi|")

f2_nomi() {
    esegui systemctl enable systemd-resolved.service
    # lo si accende subito, se no lo script resterebbe senza DNS per il resto
    # dell'installazione
    if esegui systemctl start systemd-resolved.service; then
        mkdir -p "$(percorso /etc)"
        ln -sfn /run/systemd/resolve/stub-resolv.conf "$(percorso /etc/resolv.conf)"
    else
        avviso "systemd-resolved non parte: lascio /etc/resolv.conf com'e'"
    fi
    ok "Nomi dei siti con systemd-resolved"
}
# ===== 45-caelestia.sh
# --- oversicaOS: Caelestia (l'interfaccia) e i suoi pezzi, a versione fissa ----------
# Caelestia (https://github.com/caelestia-dots, licenza GPL-3) si scarica con git a un
# commit fisso: il commit e' anche il controllo che il codice sia quello giusto.
CAELESTIA_SHELL_URL="https://github.com/caelestia-dots/shell"
CAELESTIA_SHELL_COMMIT="bcbb5d5139d5159839c7362d8f4954ccc7dbd67d"
CAELESTIA_CLI_URL="https://github.com/caelestia-dots/cli"
CAELESTIA_CLI_COMMIT="fdb3e47038c77ec8e7bb6010ffbcae00501d420b"
QUICKSHELL_GIT_URL="https://github.com/quickshell-mirror/quickshell"
QUICKSHELL_COMMIT="9b0f339b19057f4731bf3b48293307d7ef241671"
M3SHAPES_URL="https://github.com/soramanew/m3shapes"
M3SHAPES_COMMIT="32ad9ce328bb77ed349b40a3be10ee9ea610b8ab"
MATERIALYOU_URL="https://files.pythonhosted.org/packages/eb/23/2e63e7bdfcc1aa7ba955386ad09e3bd8a535a1092d7af501659b63cb6282/materialyoucolor-3.0.4.tar.gz"
MATERIALYOU_SHA256="30b8dde034dce180845b0eaf52f72c5b22cd5b60bd7aff96804febae4e266276"

# scarica_git URL COMMIT CARTELLA: i sorgenti di URL esattamente al COMMIT (3 tentativi)
scarica_git() {
    local url=$1 commit=$2 dir=$3 nome=${1##*/} volta
    for volta in 1 2 3; do
        rm -rf "$dir"
        mkdir -p "$dir"
        if esegui git -C "$dir" init -q \
            && esegui git -C "$dir" remote add origin "$url" \
            && esegui git -C "$dir" fetch -q --depth 1 origin "$commit" \
            && esegui git -C "$dir" checkout -q FETCH_HEAD \
            && [ "$(esegui git -C "$dir" rev-parse HEAD)" = "$commit" ]; then
            return 0
        fi
        avviso "Scaricare $nome non e' riuscito (tentativo $volta di 3)"
        [ -n "$VETRO_RADICE" ] || sleep $((volta * 5))
    done
    rm -rf "$dir"
    muori "Non riesco a scaricare $nome alla versione giusta ($commit): controlla la rete e rilancia"
}

# scarica_controllato URL SHA256 FILE: scarica e controlla l'impronta
scarica_controllato() {
    local url=$1 sha=$2 file=$3
    mkdir -p "$(dirname "$file")"
    if ! esegui curl -fL --retry 3 -o "$file" "$url"; then
        rm -f "$file"
        muori "Non riesco a scaricare ${url##*/}: controlla la rete e rilancia"
    fi
    if [ "$(sha256sum "$file" | cut -d' ' -f1)" != "$sha" ]; then
        rm -f "$file"
        muori "Il file ${url##*/} non passa il controllo (sha256): non lo uso"
    fi
}

# applica_ritocchi SORGENTE: i ritocchi di oversicaOS (vedi usr/local/lib/vetro/caelestia/LEGGIMI)
applica_ritocchi() {
    local s=$1 r=${CAELESTIA_RITOCCHI:-$VETRO_FILE/usr/local/lib/vetro/caelestia} p
    if [ -d "$r/nuovi" ]; then
        cp -a "$r/nuovi/." "$s/" || muori "Non riesco a copiare i file di oversicaOS su Caelestia"
    fi
    for p in "$r"/ritocchi/*.patch; do
        [ -f "$p" ] || continue
        if ! patch -d "$s" -p1 --forward --batch --fuzz=0 --no-backup-if-mismatch -r - < "$p" >/dev/null; then
            muori "Un ritocco di oversicaOS non si applica a Caelestia (${p##*/}): lfs.sh va aggiornato (mandami questo messaggio)"
        fi
    done
    info "Ritocchi di oversicaOS applicati"
}

# I pacchetti ufficiali che servono a Caelestia (compilarlo e usarlo)
PKG_CAELESTIA=(git gettext cmake ninja pkgconf qt6-base qt6-declarative qt6-imageformats
               qt6-multimedia qt6-shadertools qt6-svg qt6-wayland pipewire libqalculate aubio
               cava ddcutil brightnessctl lm_sensors power-profiles-daemon networkmanager
               fish swappy grim slurp wl-clipboard cliphist fuzzel ffmpeg libnotify glib2
               ttf-cascadia-code-nerd python-build python-installer python-hatchling
               python-hatch-vcs python-setuptools python-wheel pybind11 python-pillow)
CAELESTIA_VERSIONE=2.5.0       # l'ultima versione con nome prima del commit fisso
CAELESTIA_CLI_VERSIONE=1.1.3

# compila_caelestia: m3shapes, materialyoucolor, cli e shell di Caelestia (con i
# ritocchi di oversicaOS), installati nel sistema
compila_caelestia() {
    local t; t=$(mktemp -d)
    installa_pacchetti "${PKG_CAELESTIA[@]}"
    # le barre della musica: libcava viene dal pacchetto cava di Arch
    esegui pkg-config --exists libcava || esegui pkg-config --exists cava \
        || { rm -rf "$t"; muori "Manca libcava (pacchetto cava): lfs.sh va aggiornato (mandami questo messaggio)"; }

    info "Compilo le forme di Caelestia (m3shapes)"
    scarica_git "$M3SHAPES_URL" "$M3SHAPES_COMMIT" "$t/m3shapes"
    esegui cmake -S "$t/m3shapes" -B "$t/m3shapes-build" -G Ninja -DCMAKE_BUILD_TYPE=Release \
            -DCMAKE_INSTALL_PREFIX=/ \
        && esegui cmake --build "$t/m3shapes-build" \
        && esegui cmake --install "$t/m3shapes-build" \
        || { rm -rf "$t"; muori "Le forme di Caelestia (m3shapes) non si compilano"; }

    info "Preparo i colori presi dallo sfondo (materialyoucolor)"
    scarica_controllato "$MATERIALYOU_URL" "$MATERIALYOU_SHA256" "$t/materialyoucolor.tar.gz"
    esegui tar -xzf "$t/materialyoucolor.tar.gz" -C "$t" \
        && esegui python3 -m build --wheel --no-isolation --outdir "$t/ruote" "$t/materialyoucolor-3.0.4" \
        || { rm -rf "$t"; muori "materialyoucolor non si compila"; }

    info "Compilo il comando di Caelestia (cli)"
    scarica_git "$CAELESTIA_CLI_URL" "$CAELESTIA_CLI_COMMIT" "$t/caelestia-cli"
    SETUPTOOLS_SCM_PRETEND_VERSION=$CAELESTIA_CLI_VERSIONE \
        esegui python3 -m build --wheel --no-isolation --outdir "$t/ruote" "$t/caelestia-cli" \
        || { rm -rf "$t"; muori "Il comando di Caelestia (cli) non si compila"; }
    local ruota
    for ruota in "$t"/ruote/*.whl; do
        esegui python3 -m installer --overwrite-existing "$ruota" \
            || { rm -rf "$t"; muori "Non riesco a installare ${ruota##*/}"; }
    done

    info "Compilo Caelestia (l'interfaccia di oversicaOS, qualche minuto)"
    scarica_git "$CAELESTIA_SHELL_URL" "$CAELESTIA_SHELL_COMMIT" "$t/caelestia-shell"
    applica_ritocchi "$t/caelestia-shell"
    esegui cmake -S "$t/caelestia-shell" -B "$t/caelestia-shell-build" -G Ninja \
            -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX=/ \
            -DVERSION="$CAELESTIA_VERSIONE" -DGIT_REVISION="$CAELESTIA_SHELL_COMMIT" -DDISTRIBUTOR=oversicaOS \
            "-DENABLE_MODULES=extras;plugin;shell" \
        && esegui cmake --build "$t/caelestia-shell-build" \
        && esegui cmake --install "$t/caelestia-shell-build" \
        || { rm -rf "$t"; muori "Caelestia non si compila: mandami il registro (sudo bash lfs.sh registri)"; }
    rm -rf "$t"
    ok "Caelestia compilato e installato"
}

# si controlla all'inizio che ci siano tutti (come gli altri pacchetti del desktop)
PKG_FASE2+=("${PKG_CAELESTIA[@]}")
# ===== 50-fase3-programmi.sh
# --- Fase 3: i programmi ------------------------------------------------------------------
# Tor Browser (l'unico browser), posta, ufficio, file, testi, terminale e i programmi
# Windows (Wine, sempre nel recinto). Wine sta nel deposito "multilib".
PKG_FASE3=(torbrowser-launcher thunderbird thunderbird-i18n-it libreoffice-fresh
           libreoffice-fresh-it thunar mousepad foot yad wine wine-mono wine-gecko
           bubblewrap xdg-utils)
FILE_PROGRAMMI="usr/local/bin/tor-browser usr/local/bin/browser-predefinito usr/local/bin/wine
                usr/local/lib/wine-recinto/xdg-open etc/xdg/mimeapps.list
                usr/share/applications/tor-browser.desktop
                usr/local/share/applications/torbrowser.desktop
                usr/local/share/applications/wine.desktop"
FASE3=("programmi|f3_programmi|$(echo $FILE_PROGRAMMI)")

# i comandi di Wine che passano anche loro dal recinto (se Wine li ha)
STRUMENTI_WINE="msidb msiexec notepad regedit regsvr32 wineboot winecfg wineconsole winedbg
                winefile winemine winepath wineserver"

f3_programmi() {
    local t
    abilita_multilib
    installa_pacchetti "${PKG_FASE3[@]}"
    # shellcheck disable=SC2086
    installa_file $FILE_PROGRAMMI
    for t in $STRUMENTI_WINE; do
        if [ -e "$(percorso "/usr/bin/$t")" ]; then
            ln -sfn wine "$(percorso "/usr/local/bin/$t")"
        fi
    done
    ok "Programmi: Tor Browser, Thunderbird, LibreOffice, Thunar, Mousepad, foot, Wine nel recinto"
}
# ===== 60-fase4-sicurezza.sh
# --- Fase 4: sicurezza ----------------------------------------------------------------------
# Firewall (nessuno entra da fuori), Guardiano della rete (chiede prima che un programma
# esca), modalita' fantasma (tutto da Tor, accesa di serie) e l'utente fantasma.
PKG_FASE4=(iptables tor wireguard-tools)
FILE_SICUREZZA="etc/modules-load.d/vetro.conf usr/local/sbin/firewall-avvia
                usr/local/sbin/guardiano-rete usr/local/sbin/fantasma-aiuto
                usr/local/bin/guardiano-avvisi usr/local/bin/guardiano-regole usr/local/bin/fantasma
                usr/local/lib/fantasma etc/systemd/system/firewall.service
                etc/systemd/system/guardiano-rete.service etc/systemd/system/tor-fantasma.service
                etc/systemd/system/fantasma-avvio.service etc/sudoers.d/30-fantasma
                usr/share/applications/fantasma.desktop usr/share/applications/guardiano-regole.desktop"
FILE_UTENTE_FANTASMA="etc/systemd/system/home-fantasma.mount etc/systemd/system/fantasma-casa.service
                      etc/sudoers.d/31-utente-fantasma usr/local/share/fantasma/casa"
FILE_VPN="usr/local/sbin/vpn-aiuto usr/local/bin/vpn etc/systemd/system/vpn.service
          etc/sudoers.d/20-vpn usr/share/applications/vpn.desktop"
FILE_CASSAFORTE="usr/local/bin/cassaforte usr/share/applications/cassaforte.desktop
                 usr/share/applications/cassaforte-chiudi.desktop"
# DNS, VPN e cassaforte PRIMA della modalita' fantasma: accesa di serie, scrive il DNS
# verso Tor, e dopo non si deve piu' toccare systemd-resolved (installazione senza DNS)
FASE4=("dns|f4_dns|etc/systemd/resolved.conf.d/10-vetro-dns.conf"
       "vpn|f4_vpn|$(echo $FILE_VPN)"
       "cassaforte|f4_cassaforte|$(echo $FILE_CASSAFORTE)"
       "fantasma|f4_fantasma|$(echo $FILE_SICUREZZA)"
       "utente-fantasma|f4_utente_fantasma|$(echo $FILE_UTENTE_FANTASMA)"
       "rete|f4_rete|etc/NetworkManager/conf.d/10-oversica.conf")

# installa solo i pacchetti che mancano: "pacman -T" guarda anche chi li fornisce (es.
# iptables-nft al posto di iptables, che pacman --noconfirm non sostituirebbe)
installa_se_mancano() {
    local mancano
    mancano=$(esegui pacman -T "$@") || true
    # shellcheck disable=SC2086
    if [ -n "$mancano" ]; then installa_pacchetti $mancano; fi
}

# il DNS cifrato (Quad9, DNS-over-TLS): vale dal prossimo avvio (systemd-resolved non
# si riavvia adesso, cosi' l'installazione non resta senza nomi se la rete blocca il TLS)
f4_dns() {
    installa_file etc/systemd/resolved.conf.d/10-vetro-dns.conf
    ok "DNS cifrato (Quad9), dal prossimo avvio"
}

# la VPN WireGuard: si sceglie il file e si accende dal menu (VPN)
f4_vpn() {
    installa_se_mancano wireguard-tools
    # wg-quick passa i DNS della VPN a "resolvconf": con systemd-resolved e' systemd-resolvconf
    if [ -n "$(esegui pacman -T resolvconf || true)" ]; then
        installa_pacchetti systemd-resolvconf
    fi
    # shellcheck disable=SC2086
    installa_file $FILE_VPN
    esegui visudo -cf "$(percorso /etc/sudoers.d/20-vpn)"
    ok "VPN WireGuard (si accende dal menu: VPN)"
}

# la cassaforte usa la cifratura di ext4 (fscrypt): serve la funzione "encrypt" del disco
f4_cassaforte() {
    local tipo disco caratteristiche
    tipo=$(esegui findmnt -no FSTYPE -T /home 2>/dev/null || true)
    if [ "$tipo" != ext4 ]; then
        avviso "La cassaforte ha bisogno di ext4: la salto"
        return 0
    fi
    disco=$(esegui findmnt -no SOURCE -T /home)
    caratteristiche=$(esegui dumpe2fs -h "$disco" 2>/dev/null || true)
    if ! grep -qw encrypt <<<"$caratteristiche"; then
        esegui tune2fs -O encrypt "$disco"
    fi
    # shellcheck disable=SC2086
    installa_file $FILE_CASSAFORTE
    ok "Cassaforte (cartella cifrata)"
}

f4_fantasma() {
    local p u
    installa_se_mancano "${PKG_FASE4[@]}"
    for p in $FILE_SICUREZZA; do
        if [ -d "$VETRO_FILE/$p" ]; then installa_cartella "$p"; else installa_file "$p"; fi
    done
    esegui visudo -cf "$(percorso /etc/sudoers.d/30-fantasma)"
    # le regole del Guardiano: il servizio puo' scrivere solo li' (ReadWritePaths), e
    # senza la cartella non parte (e i tuoi programmi resterebbero senza internet)
    mkdir -p "$(percorso /etc/guardiano-rete)"
    chmod 755 "$(percorso /etc/guardiano-rete)"
    p=$(percorso /etc/guardiano-rete/regole)
    [ -f "$p" ] || printf '# Regole del Guardiano della rete: permetti/blocca <TAB> programma\n' > "$p"
    chmod 644 "$p"
    # il gruppo che risponde alle domande del Guardiano
    u=$(utente_vetro) || exit 1
    esegui groupadd -f guardiano
    esegui usermod -aG guardiano "$u"
    # icona del fantasma (lo sfondo non cambia piu': in oversicaOS c'e' l'icona nella barra)
    rm -f "$(percorso /usr/share/backgrounds/sfondo-fantasma.png)"
    for p in 32 48 64 128 256; do
        mkdir -p "$(percorso "/usr/share/icons/hicolor/${p}x${p}/apps")"
        esegui python3 -I "$(percorso /usr/local/lib/fantasma/disegna-fantasma)" icona \
               "$(percorso "/usr/share/icons/hicolor/${p}x${p}/apps/fantasma.png")" "$p"
    done
    esegui gtk-update-icon-cache -qtf "$(percorso /usr/share/icons/hicolor)" || true
    # Thunderbird in modalita' fantasma avvisa prima di aprirsi
    if [ -e "$(percorso /usr/bin/thunderbird)" ]; then
        ln -sfn ../lib/fantasma/avviso-fantasma "$(percorso /usr/local/bin/thunderbird)"
    fi
    # accesa di serie, una volta sola: se poi la spegni, rifacendo il passo resta spenta
    if [ ! -e "$(percorso /etc/fantasma/predefinita)" ]; then
        esegui python3 -I "$(percorso /usr/local/sbin/fantasma-aiuto)" prepara
        mkdir -p "$(percorso /etc/fantasma)"
        touch "$(percorso /etc/fantasma/predefinita)"
    fi
    esegui systemctl enable fantasma-avvio.service firewall.service guardiano-rete.service
    ok "Firewall, Guardiano della rete e modalita' fantasma (accesa)"
}

f4_utente_fantasma() {
    local uid gid
    if ! esegui id fantasma >/dev/null 2>&1; then
        esegui useradd -m -G video,input,audio,guardiano -s /bin/bash \
               -c "Utente fantasma (tutto in memoria)" fantasma
    fi
    esegui usermod -aG video,input,audio,guardiano fantasma
    uid=$(esegui id -u fantasma)
    gid=$(esegui id -g fantasma)
    installa_file etc/systemd/system/fantasma-casa.service etc/sudoers.d/31-utente-fantasma
    installa_cartella usr/local/share/fantasma/casa
    esegui visudo -cf "$(percorso /etc/sudoers.d/31-utente-fantasma)"
    mkdir -p "$(percorso /etc/systemd/system)"
    sed -e "s/@UID@/$uid/" -e "s/@GID@/$gid/" "$VETRO_FILE/etc/systemd/system/home-fantasma.mount" \
        > "$(percorso /etc/systemd/system/home-fantasma.mount)"
    esegui systemctl enable home-fantasma.mount fantasma-casa.service
    ok "Utente fantasma (casa in memoria)"
}

# la password dell'utente fantasma: dall'impronta lasciata da "fase10", se c'e'; se no
# si chiede alla fine (i passi non possono chiedere niente), solo se non ce l'ha ancora
password_fantasma() {
    # installata da "fase10": l'impronta della password l'ha data il PC
    local impronta
    impronta=$(percorso /etc/vetro/fantasma.hash)
    if [ -s "$impronta" ]; then
        esegui usermod -p "$(cat "$impronta")" fantasma
        rm -f "$impronta"
        return 0
    fi
    [ -n "${VETRO_PROVA:-}" ] && return 0
    case "$(esegui passwd -S fantasma 2>/dev/null | cut -d' ' -f2 || true)" in
        L|NP) ;;
        *) return 0 ;;
    esac
    titolo "Password dell'utente fantasma (per entrare dalla schermata di accesso)"
    local volta
    for volta in 1 2 3; do
        if esegui passwd fantasma; then return 0; fi
        avviso "Password non cambiata, riprova ($volta di 3)"
    done
    avviso "Password del fantasma non impostata: la metti dopo con  sudo passwd fantasma"
}

# --- la rete: NetworkManager (lo usa Caelestia). Ultimo passo e solo dal riavvio dopo:
# adesso la rete (systemd-networkd) resta com'e', cosi' l'installazione non si interrompe
f4_rete() {
    installa_pacchetti networkmanager
    installa_file etc/NetworkManager/conf.d/10-oversica.conf
    esegui systemctl enable NetworkManager.service NetworkManager-wait-online.service
    esegui systemctl disable systemd-networkd.service systemd-networkd-wait-online.service iwd.service \
        || avviso "Non riesco a spegnere la rete vecchia: controlla dopo il riavvio"
    ok "Rete con NetworkManager (dal prossimo avvio)"
}
# ===== 80-pc.sh
# --- Il PC: la macchina virtuale con Vetro su Arch ---------------------------------------
#   sudo bash lfs.sh fase10     la prima volta installa Arch e poi Vetro; dopo aggiorna Vetro
#   sudo bash lfs.sh avvia      la accende con lo schermo
#   sudo bash lfs.sh registri | controlla   (senza schermo, risultato sul PC)
# Tutto sta in ~/vetro-arch dell'utente che ha fatto sudo (cartella_pc). QEMU gira come
# quell'utente. Un piccolo server (solo 127.0.0.1:8765, dalla macchina 10.0.2.2:8765)
# da' alla macchina lo script di installazione, le scelte e lfs.sh.
ISO_URL="https://geo.mirror.pkgbuild.com/iso/latest"
PC_PORTA=8765
QEMU=qemu-system-x86_64
VETRO_LFS=${VETRO_LFS:-}
PC_SERVER_PID=""

pc_utente() { echo "${SUDO_USER:-root}"; }

# i file della macchina appartengono all'utente (QEMU gira come lui)
pc_chown() {
    local u; u=$(pc_utente)
    [ "$u" = root ] || chown -R "$u": "$(cartella_pc)"
}

# pc_come_utente COMANDO...: come l'utente di sudo, con il suo schermo
pc_come_utente() {
    local u uid
    u=$(pc_utente)
    if [ "$u" = root ]; then esegui "$@"; return; fi
    uid=$(id -u "$u")
    local amb=(DISPLAY="${DISPLAY:-:0}")
    [ -n "${XAUTHORITY:-}" ] && amb+=(XAUTHORITY="$XAUTHORITY")
    if [ -d "/run/user/$uid" ]; then
        amb+=(XDG_RUNTIME_DIR="/run/user/$uid")
        [ -S "/run/user/$uid/wayland-0" ] && amb+=(WAYLAND_DISPLAY=wayland-0)
    fi
    esegui sudo -u "$u" env "${amb[@]}" "$@"
}

pc_qemu_pronto() {
    command -v "$QEMU" >/dev/null 2>&1 && command -v qemu-img >/dev/null 2>&1 && return 0
    titolo "Installo QEMU (la macchina virtuale)"
    if command -v dnf >/dev/null 2>&1; then
        esegui dnf install -y qemu-system-x86 qemu-img || true
        esegui dnf install -y qemu-audio-pipewire qemu-ui-gtk qemu-ui-opengl \
               qemu-device-display-virtio-vga-gl qemu-device-display-virtio-gpu-gl >/dev/null 2>&1 || true
    elif command -v apt-get >/dev/null 2>&1; then
        esegui apt-get install -y qemu-system-x86 qemu-utils || true
    fi
    command -v "$QEMU" >/dev/null 2>&1 \
        || muori "Non riesco a installare QEMU: installalo a mano (Fedora: sudo dnf install qemu-system-x86 qemu-img)"
}

# dalla lista sha256sums.txt (su stdin) la riga della ISO con la data
scegli_iso() {
    grep -E '^[0-9a-f]+ +archlinux-[0-9]{4}\.[0-9]{2}\.[0-9]{2}-x86_64\.iso$' | head -n 1 || true
}

# pc_iso -> il percorso della ISO di Arch del mese, scaricata e controllata (sha256)
pc_iso() {
    local c riga nome
    c=$(cartella_pc)
    riga=$(esegui curl -fsSL "$ISO_URL/sha256sums.txt" 2>/dev/null | scegli_iso || true)
    [ -n "$riga" ] || muori "Non riesco a leggere l'elenco delle ISO di Arch ($ISO_URL): controlla la rete"
    nome=${riga##* }
    if [ ! -f "$c/$nome" ]; then
        info "Scarico $nome (circa 1,2 GB)..." >&2
        esegui curl -fL --retry 3 -C - -o "$c/$nome.parziale" "$ISO_URL/$nome" >&2 \
            || muori "Download della ISO non riuscito: rilancia, riprende da dove era"
        mv -f "$c/$nome.parziale" "$c/$nome"
    fi
    if ! (cd "$c" && printf '%s\n' "$riga" | sha256sum -c --status); then
        rm -f "$c/$nome"
        muori "La ISO scaricata non passa il controllo (sha256): l'ho cancellata, rilancia"
    fi
    echo "$c/$nome"
}

# pc_parametri_iso CARTELLA -> i parametri di avvio di archiso (dalla ISO aperta)
pc_parametri_iso() {
    local d=$1 p
    p=$(grep -rhoE 'archisosearchuuid=[0-9A-Za-z_-]+' "$d/loader" "$d/boot" 2>/dev/null | head -n 1 || true)
    [ -n "$p" ] || p=$(grep -rhoE 'archisolabel=[0-9A-Za-z_-]+' "$d/loader" "$d/boot" 2>/dev/null | head -n 1 || true)
    [ -n "$p" ] || return 1
    echo "archisobasedir=arch $p"
}

# pc_kernel ISO: kernel, initramfs e parametri dalla ISO in ~/vetro-arch/avvio
pc_kernel() {
    local iso=$1 c m p riuscito=0
    c=$(cartella_pc)
    mkdir -p "$c/avvio"
    m=$(mktemp -d)
    esegui mount -o loop,ro "$iso" "$m" || { rmdir "$m"; muori "Non riesco ad aprire la ISO di Arch ($iso)"; }
    if cp -f "$m/arch/boot/x86_64/vmlinuz-linux" "$m/arch/boot/x86_64/initramfs-linux.img" "$c/avvio/" \
            && p=$(pc_parametri_iso "$m"); then
        echo "$p" > "$c/avvio/parametri"
        riuscito=1
    fi
    esegui umount "$m" || true
    rmdir "$m" 2>/dev/null || true
    [ "$riuscito" = 1 ] || muori "Nella ISO di Arch non trovo il kernel o i parametri di avvio"
}

# pc_impronta: la password da stdin -> la sua impronta ($6$..., come in /etc/shadow)
pc_impronta() {
    esegui openssl passwd -6 -stdin
}

# pc_chiedi_utente: nome e password (e quella del fantasma) -> condivisa/installa.conf
# (solo le impronte: la password in chiaro non esce dal PC). Nelle prove: VETRO_UTENTE,
# VETRO_PASSWORD, VETRO_PASSWORD_FANTASMA.
pc_chiedi_utente() {
    local c u p p2 pf i if_
    c=$(cartella_pc)
    mkdir -p "$c/condivisa"
    u=${VETRO_UTENTE:-}
    if [ -z "$u" ]; then
        read -r -p "  Nome del tuo utente nella macchina (minuscole, es. davide): " u
    fi
    [[ "$u" =~ ^[a-z_][a-z0-9_-]{0,31}$ ]] \
        || muori "Nome utente non valido: solo lettere minuscole, numeri, - e _ (es. davide)"
    if [ -n "${VETRO_PASSWORD+x}" ]; then
        p=$VETRO_PASSWORD
        pf=${VETRO_PASSWORD_FANTASMA:-}
    else
        while :; do
            read -r -s -p "  Password di $u: " p; echo
            read -r -s -p "  Ripetila: " p2; echo
            [ -n "$p" ] && [ "$p" = "$p2" ] && break
            avviso "Le due password non sono uguali (o sono vuote): riprova"
        done
        read -r -s -p "  Password dell'utente fantasma (Invio = la stessa): " pf; echo
    fi
    [ -n "$pf" ] || pf=$p
    i=$(printf '%s\n' "$p" | pc_impronta)
    if_=$(printf '%s\n' "$pf" | pc_impronta)
    [[ "$i" == '$6$'* && "$if_" == '$6$'* ]] || muori "Non riesco a fare l'impronta della password (manca openssl?)"
    ( umask 077; printf 'UTENTE=%q\nIMPRONTA=%q\nIMPRONTA_FANTASMA=%q\n' "$u" "$i" "$if_" > "$c/condivisa/installa.conf" )
    chmod 600 "$c/condivisa/installa.conf"
}

pc_crea_disco() {
    local d; d="$(cartella_pc)/disco.qcow2"
    rm -f "$d"
    esegui qemu-img create -f qcow2 "$d" 40G >/dev/null || muori "Non riesco a creare il disco virtuale ($d)"
}

pc_copia_lfs() {
    [ -n "$VETRO_LFS" ] && [ -f "$VETRO_LFS" ] || muori "Non trovo lfs.sh (lancialo con: sudo bash lfs.sh ...)"
    cp -f "$VETRO_LFS" "$(cartella_pc)/condivisa/lfs.sh"
}

# il server della cartella condivisa: GET per dare i file alla macchina, PUT per
# riceverli (solo nomi semplici; dei nomi col punto davanti solo .arch-ok e .esito)
PC_SERVER_PY='
import http.server, os, sys
CARTELLA = sys.argv[1]
PUNTO = {".arch-ok", ".esito"}
class Gestore(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *a, **k):
        super().__init__(*a, directory=CARTELLA, **k)
    def log_message(self, *a):
        pass
    def do_PUT(self):
        nome = os.path.basename(self.path.split("?", 1)[0]) or "file"
        lunghezza = int(self.headers.get("Content-Length", "0"))
        if (nome.startswith(".") and nome not in PUNTO) or lunghezza > 200 * 1024 * 1024:
            self.send_error(403); return
        with open(os.path.join(CARTELLA, nome), "wb") as f:
            f.write(self.rfile.read(lunghezza))
        self.send_response(201); self.end_headers()
http.server.ThreadingHTTPServer(("127.0.0.1", int(sys.argv[2])), Gestore).serve_forever()
'

pc_server_avvia() {
    [ -n "$PC_SERVER_PID" ] && kill -0 "$PC_SERVER_PID" 2>/dev/null && return 0
    local c; c=$(cartella_pc)
    pc_chown
    pc_come_utente python3 -I -c "$PC_SERVER_PY" "$c/condivisa" "$PC_PORTA" >/dev/null 2>&1 &
    PC_SERVER_PID=$!
    local _
    for _ in $(seq 1 25); do
        curl -fs -o /dev/null "http://127.0.0.1:$PC_PORTA/lfs.sh" && return 0
        sleep 0.2
    done
    muori "Il piccolo server per la macchina non parte: la porta $PC_PORTA e' occupata? (chiudi un altro lfs.sh e rilancia)"
}

pc_server_ferma() {
    [ -n "$PC_SERVER_PID" ] || return 0
    kill "$PC_SERVER_PID" 2>/dev/null || true
    PC_SERVER_PID=""
}

# pc_qemu installa|comando|avvia -> il comando di QEMU in COMANDO
pc_qemu() {
    local modo=$1 c cpu aiuto_dev aiuto_audio drv
    c=$(cartella_pc)
    cpu=$(( $(nproc) / 2 )); [ "$cpu" -ge 2 ] || cpu=2
    aiuto_dev=$(esegui "$QEMU" -device help 2>/dev/null || true)
    aiuto_audio=$(esegui "$QEMU" -audiodev help 2>/dev/null || true)
    COMANDO=("$QEMU" -name "Vetro su Arch")
    # KVM (il processore che aiuta la macchina virtuale): si guarda come l'utente di QEMU
    if pc_come_utente test -w /dev/kvm 2>/dev/null; then COMANDO+=(-machine q35,accel=kvm -cpu host)
    else COMANDO+=(-machine q35,accel=tcg -cpu max); fi
    COMANDO+=(-m "${RAM:-8192}" -smp "$cpu"
              -drive "file=$c/disco.qcow2,format=qcow2,if=virtio"
              -nic user,model=virtio-net-pci
              -device qemu-xhci -device usb-tablet)
    if grep -q '"virtio-9p-pci"' <<<"$aiuto_dev"; then
        COMANDO+=(-virtfs "local,path=$c/condivisa,mount_tag=vetro,security_model=mapped-xattr")
    fi
    case "$modo" in
        installa)
            local iso
            iso=$(ls -1 "$c"/archlinux-*-x86_64.iso 2>/dev/null | sort | tail -n 1 || true)
            COMANDO+=(-kernel "$c/avvio/vmlinuz-linux" -initrd "$c/avvio/initramfs-linux.img"
                      -append "$(cat "$c/avvio/parametri" 2>/dev/null) script=http://10.0.2.2:$PC_PORTA/installa-arch console=tty0 console=ttyS0,115200 systemd.mask=serial-getty@ttyS0.service"
                      -cdrom "$iso" -display none -serial file:/dev/stdout -no-reboot) ;;
        comando)
            COMANDO+=(-display none -serial file:/dev/stdout -no-reboot) ;;
        avvia)
            # schermo: due uscite (per provare piu' schermi), con il 3D del PC se c'e'
            if grep -q '"virtio-vga-gl"' <<<"$aiuto_dev" && [ "${GL:-si}" != no ]; then
                COMANDO+=(-vga none -device virtio-vga-gl,max_outputs=2,xres=1920,yres=1080
                          -display gtk,gl=on,zoom-to-fit=on)
            else
                COMANDO+=(-vga none -device virtio-vga,max_outputs=2,xres=1920,yres=1080
                          -display gtk,zoom-to-fit=on)
            fi
            # il suono va al PC (PipeWire o PulseAudio)
            for drv in pipewire pa alsa; do
                if grep -qw "$drv" <<<"$aiuto_audio"; then
                    COMANDO+=(-audiodev "$drv,id=suono" -device intel-hda -device hda-duplex,audiodev=suono)
                    break
                fi
            done ;;
    esac
}

# scrive un comando da copiare nel terminale (virgolette solo dove servono)
mostra_comando() {
    local a riga=""
    for a in "$@"; do
        if [[ "$a" =~ ^[A-Za-z0-9_,.:=/+@%-]+$ ]]; then riga+="$a "
        else riga+="'${a//\'/\'\\\'\'}' "; fi
    done
    printf '%s\n' "${riga% }"
}

# senza KVM tutto e' molto piu' lento: si dice perche' e come rimediare
pc_avviso_kvm() {
    avviso "Senza KVM la macchina e' molto lenta (anche ore). Attiva la virtualizzazione"
    avviso "(Intel VT-x / AMD-V) nel BIOS del PC; su Ubuntu: sudo usermod -aG kvm $(pc_utente)"
}

# pc_accendi MODO: accende la macchina (senza schermo per installa e comando)
pc_accendi() {
    pc_qemu "$1"
    case " ${COMANDO[*]} " in *"accel=tcg"*) pc_avviso_kvm ;; esac
    pc_chown
    pc_come_utente "${COMANDO[@]}" || true
}

pc_fase10() {
    serve_root fase10
    local c iso
    c=$(cartella_pc)
    mkdir -p "$c/condivisa" "$c/avvio"
    pc_qemu_pronto
    if [ ! -f "$c/condivisa/.arch-ok" ]; then
        titolo "1/2 - Installo Arch nella macchina virtuale (solo la prima volta)"
        [ -s "$c/condivisa/installa.conf" ] || pc_chiedi_utente
        iso=$(pc_iso)
        pc_crea_disco
        pc_kernel "$iso"
        cp -f "$VETRO_FILE/usr/local/lib/vetro/installa-arch" "$c/condivisa/installa-arch" 2>/dev/null || true
        pc_copia_lfs
        rm -f "$c/condivisa/installa-arch.log"
        pc_server_avvia
        info "La macchina parte senza schermo: qui sotto i suoi messaggi (ci vuole un po')."
        info "Non scrivere niente: fa tutto da sola (le domande di pacman hanno gia' la risposta)."
        pc_accendi installa
        [ -f "$c/condivisa/.arch-ok" ] \
            || muori "L'installazione di Arch non e' riuscita (il motivo e' in $c/condivisa/installa-arch.log). Rilancia:  sudo bash lfs.sh fase10"
        ok "Arch installato"
    fi
    rm -f "$c/condivisa/installa.conf"
    titolo "2/2 - Installo (o aggiorno) Vetro nella macchina"
    info "Non scrivere niente: fa tutto da sola. Se compare \"login:\", ignoralo."
    pc_copia_lfs
    rm -f "$c/condivisa/.esito"
    echo installa > "$c/condivisa/.comando"
    pc_server_avvia
    pc_accendi comando
    rm -f "$c/condivisa/.comando"
    if [ "$(cat "$c/condivisa/.esito" 2>/dev/null)" = ok ]; then
        titolo "Fatto. Ora:  sudo bash lfs.sh avvia"
    else
        muori "Vetro non si e' installato del tutto: guarda i messaggi qui sopra, poi rilancia  sudo bash lfs.sh fase10  (riprende da dove era)"
    fi
}

# pc_comando registri|controlla: la macchina lo esegue senza schermo e si spegne
pc_comando() {
    serve_root "$1"
    local c; c=$(cartella_pc)
    [ -f "$c/disco.qcow2" ] || muori "La macchina virtuale non c'e' ancora: prima  sudo bash lfs.sh fase10"
    pc_copia_lfs
    rm -f "$c/condivisa/.esito"
    echo "$1" > "$c/condivisa/.comando"
    pc_server_avvia
    pc_accendi comando
    rm -f "$c/condivisa/.comando"
    if [ "$1" = registri ]; then
        ok "I registri sono in: $c/condivisa/registri-vetro.txt"
    fi
}

pc_avvia() {
    local prova=${1:-} c t0 esito=0
    [ "$prova" = --prova ] || serve_root avvia
    c=$(cartella_pc)
    [ -f "$c/disco.qcow2" ] || [ "$prova" = --prova ] \
        || muori "La macchina virtuale non c'e' ancora: prima  sudo bash lfs.sh fase10"
    rm -f "$c/condivisa/.comando"
    pc_qemu avvia
    if [ "$prova" = --prova ]; then
        mostra_comando "${COMANDO[@]}"
        return 0
    fi
    info "Chiudi la finestra per spegnere. Schermo intero: Ctrl+Alt+F."
    pc_chown
    t0=$SECONDS
    pc_come_utente "${COMANDO[@]}" || esito=$?
    # con il 3D QEMU a volte non apre la finestra: si riprova senza
    if [ "$esito" -ne 0 ] && [ $(( SECONDS - t0 )) -lt 20 ] && [ "${GL:-si}" != no ]; then
        avviso "QEMU non e' partito con il 3D: riprovo senza"
        GL=no pc_qemu avvia
        pc_come_utente "${COMANDO[@]}" || true
    fi
}
# ===== 90-comandi.sh
# --- i comandi --------------------------------------------------------------------

aiuto() {
    cat <<'EOF'
lfs.sh — Vetro su Arch Linux (il desktop Vetro, leggero, con la modalita' fantasma)

Sul tuo PC (Fedora, Ubuntu...), con una macchina virtuale:
  sudo bash lfs.sh fase10      crea la macchina con Arch e Vetro (la prima volta),
                               oppure aggiorna Vetro dentro la macchina
  sudo bash lfs.sh avvia       accende la macchina con lo schermo
  sudo bash lfs.sh registri    raccoglie i registri della macchina in un file
  sudo bash lfs.sh controlla   dice come sta la macchina

Dentro un Arch gia' installato (anche un PC vero):
  sudo bash lfs.sh installa    installa o aggiorna Vetro su questo computer
  sudo bash lfs.sh controlla   a che punto e' il sistema
  sudo bash lfs.sh registri    raccoglie i registri in un file
  sudo bash lfs.sh rifai PASSO rifa' un passo
EOF
}

# la cartella della macchina virtuale sul PC: ~/vetro-arch dell'utente che ha fatto sudo
cartella_pc() {
    local u=${SUDO_USER:-root} casa
    casa=$(getent passwd "$u" 2>/dev/null | cut -d: -f6)
    printf '%s\n' "${VETRO_PC:-${casa:-/root}/vetro-arch}"
}

# dove_sono -> "arch" (dentro Arch, si lavora su questo computer) | "pc" (sul PC
# con la macchina virtuale)
dove_sono() {
    if [ -f "$(percorso /etc/arch-release)" ] && [ ! -f "$(cartella_pc)/disco.qcow2" ]; then
        echo arch
    else
        echo pc
    fi
}

# all'uscita: ferma il server della macchina (se c'e') e toglie i file estratti
pulisci() {
    if declare -F pc_server_ferma >/dev/null; then pc_server_ferma; fi
    if [ -n "${VETRO_FILE_TEMP:-}" ]; then rm -rf "$VETRO_FILE_TEMP"; fi
}

# un comando del pezzo "PC" (80-pc.sh): se manca, un messaggio chiaro
comando_pc() {
    declare -F "$1" >/dev/null || muori "Questo lfs.sh non sa gestire la macchina virtuale"
    "$@"
}

cmd_tutto() {
    serve_root installa
    controlla_arch
    # (pacchetti: li aggiunge il pezzo dei pacchetti, se c'e')
    if declare -F abilita_multilib >/dev/null; then abilita_multilib; fi
    if declare -F controlla_tutti_i_pacchetti >/dev/null; then controlla_tutti_i_pacchetti; fi
    titolo "Fase 1 - sistema leggero";      esegui_fase "${FASE1[@]}"
    titolo "Fase 2 - desktop";               esegui_fase "${FASE2[@]}"
    titolo "Fase 3 - programmi";             esegui_fase "${FASE3[@]}"
    titolo "Fase 4 - sicurezza";             esegui_fase "${FASE4[@]}"
    if declare -F password_fantasma >/dev/null; then password_fantasma; fi
    titolo "Fatto. Riavvia il computer:  reboot"
    mkdir -p "$VETRO_STATO"
    date '+%F %T' > "$VETRO_STATO/installato"
}

# passi non ancora fatti (per "controlla")
passi_mancanti() {
    local riga nome fn file
    for riga in "${FASE1[@]}" "${FASE2[@]}" "${FASE3[@]}" "${FASE4[@]}"; do
        IFS='|' read -r nome fn file <<<"$riga"
        [ -f "$VETRO_STATO/fatto/$nome" ] || echo "$nome"
    done
}

# controllo ESITO TESTO: [OK] se ESITO e' 0, [!!] se no
controllo() {
    if [ "$1" -eq 0 ]; then ok "$2"; else avviso "$2"; fi
}

# la RAM usata in MB (totale meno disponibile)
ram_usata_mb() {
    awk '/^MemTotal:/ {t = $2} /^MemAvailable:/ {a = $2} END { if (t) print int((t - a) / 1024) }' \
        "$(percorso /proc/meminfo)" 2>/dev/null
}

SERVIZI_VETRO="greetd NetworkManager firewall guardiano-rete systemd-oomd"

cmd_controlla() {
    local ram s m
    titolo "Come sta Vetro"
    ram=$(ram_usata_mb)
    if [ -n "$ram" ]; then
        controllo "$([ "$ram" -lt 700 ] && echo 0 || echo 1)" "RAM usata: $ram MB"
    fi
    for s in $SERVIZI_VETRO; do
        if esegui systemctl is-active --quiet "$s.service" 2>/dev/null; then
            ok "Servizio $s attivo"
        else
            avviso "Servizio $s non attivo"
        fi
    done
    if [ -e "$(percorso /sys/block/zram0)" ]; then ok "zram (memoria compressa) acceso"
    else avviso "zram (memoria compressa) non c'e'"; fi
    if [ -e "$(percorso /etc/fantasma/attivo)" ]; then
        ok "Modalita' fantasma accesa"
        if esegui "$(percorso /usr/local/sbin/fantasma-aiuto)" pronto 2>/dev/null; then
            ok "Tor collegato"
        else
            avviso "Tor non ancora collegato (internet resta bloccato finche' non si collega)"
        fi
    else
        info "Modalita' fantasma spenta"
    fi
    m=$(passi_mancanti)
    if [ -z "$m" ]; then ok "Tutti i passi sono fatti"
    else avviso "Passi non fatti: $(echo "$m" | tr '\n' ' ')"; fi
}

# sezione TITOLO: l'intestazione di una parte del file dei registri
sezione() { printf '\n=== %s\n' "$1"; }

# il contenuto dei registri (per cmd_registri)
scrivi_registri() {
    local f nome u casa uid
    sezione "Sistema"
    date '+%F %T'
    uname -r 2>/dev/null
    echo "RAM usata: $(ram_usata_mb) MB"
    sezione "Passi falliti"
    for f in "$VETRO_STATO"/registri/*.log; do
        [ -f "$f" ] || continue
        nome=$(basename "$f" .log)
        [ -f "$VETRO_STATO/fatto/$nome" ] && continue
        echo "--- $nome"
        tail -n 100 "$f"
    done
    sezione "Registro di sistema (avvisi)"
    esegui journalctl -b -p warning --no-pager 2>/dev/null | tail -n 300
    # la volta prima (registri della macchina virtuale: si accende apposta per raccoglierli)
    sezione "Registro di sistema, accensione precedente (avvisi)"
    esegui journalctl -b -1 -p warning --no-pager 2>/dev/null | tail -n 300
    u=$(utente_vetro 2>/dev/null) || u=""
    [ -n "$u" ] || return 0
    casa=$(esegui getent passwd "$u" 2>/dev/null | cut -d: -f6)
    [ -n "$casa" ] || casa="/home/$u"
    sezione "Hyprland"
    tail -n 300 "$(percorso "$casa/.cache/hyprland.log")" 2>/dev/null
    sezione "Pannelli (Quickshell)"
    tail -n 300 "$(percorso "$casa/.cache/quickshell-vetro.log")" 2>/dev/null
    sezione "Schermi e finestre"
    if esegui pgrep -u "$u" -x Hyprland >/dev/null 2>&1; then
        uid=$(esegui id -u "$u" 2>/dev/null)
        for f in monitors devices layers; do
            echo "--- hyprctl $f"
            esegui runuser -u "$u" -- env XDG_RUNTIME_DIR="/run/user/$uid" hyprctl -i 0 "$f" 2>&1
        done
    else
        echo "(il desktop non e' acceso)"
    fi
}

cmd_registri() {
    local cartella file
    cartella=$(percorso /mnt/vetro)
    # la cartella condivisa con il PC (vetro-vm.sh), se c'e'; se no quella di root
    [ -d "$cartella" ] || cartella=$(percorso /root)
    mkdir -p "$cartella"
    file="$cartella/registri-vetro.txt"
    scrivi_registri > "$file" 2>&1 || true
    ok "Registri raccolti in: ${file#"$VETRO_RADICE"}"
}

cmd_rifai() {
    serve_root rifai
    [ -n "${1:-}" ] || muori "Quale passo? Esempio:  sudo bash lfs.sh rifai desktop"
    rifai_passo "$1"
    ok "Il passo $1 si rifa' al prossimo lancio"
}

# estrae l'archivio dei file messo in fondo al file unico (lo aggiunge costruisci.sh)
estrai_archivio() {
    local dir=$1
    mkdir -p "$dir"
    sed -n '/^__VETRO_ARCHIVIO__$/,$p' "${BASH_SOURCE[0]}" | tail -n +2 | base64 -d | tar -xz -C "$dir"
}

principale() {
    case "${1:-aiuto}" in
        installa|tutto)   cmd_tutto ;;
        fase10)           comando_pc pc_fase10 "${@:2}" ;;
        avvia)            comando_pc pc_avvia "${@:2}" ;;
        controlla|registri)
            if [ "$(dove_sono)" = arch ]; then "cmd_$1"; else comando_pc pc_comando "$1"; fi ;;
        rifai)            cmd_rifai "${2:-}" ;;
        _estrai)          estrai_archivio "${2:?cartella}" ;;
        aiuto|-h|--help)  aiuto ;;
        *)                aiuto; exit 1 ;;
    esac
}
# ===== avvio
if [ "${BASH_SOURCE[0]}" = "$0" ]; then
    VETRO_LFS=${VETRO_LFS:-$(readlink -f "${BASH_SOURCE[0]}")}
    trap pulisci EXIT
    if [ -z "${VETRO_FILE:-}" ]; then
        VETRO_FILE=$(mktemp -d)
        VETRO_FILE_TEMP=$VETRO_FILE
        estrai_archivio "$VETRO_FILE"
    fi
    principale "$@"
fi
return 0 2>/dev/null || exit 0
